// FindCredential retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindCredential(ctx context.Context, exec boil.ContextExecutor, iD int64, selectCols ...string) (*Credential, error) {
	credentialObj := &Credential{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from \"credentials\" where \"id\"=$1", sel,
	)

	q := queries.Raw(query, iD)

	err := q.Bind(ctx, exec, credentialObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "master: unable to select from credentials")
	}

	if err = credentialObj.doAfterSelectHooks(ctx, exec); err != nil {
		return credentialObj, err
	}

	return credentialObj, nil
}

